"use client";

import { useDocsSearch } from "fumadocs-core/search/client";
import {
	SearchDialog,
	SearchDialogClose,
	SearchDialogContent,
	SearchDialogFooter,
	SearchDialogHeader,
	SearchDialogIcon,
	SearchDialogInput,
	SearchDialogList,
	SearchDialogOverlay,
	type SharedProps,
	TagsList,
	TagsListItem,
} from "fumadocs-ui/components/dialog/search";
import { useState } from "react";

export default function CustomSearchDialog(props: SharedProps) {
	const [tag, setTag] = useState<string | undefined>("all");
	// When tag is "all", don't filter by tag (pass undefined)
	const { search, setSearch, query } = useDocsSearch({
		type: "fetch",
		tag: tag === "all" ? undefined : tag,
	});

	return (
		<SearchDialog
			search={search}
			onSearchChange={setSearch}
			isLoading={query.isLoading}
			{...props}
		>
			<SearchDialogOverlay />
			<SearchDialogContent>
				<SearchDialogHeader>
					<SearchDialogIcon />
					<SearchDialogInput />
					<SearchDialogClose />
				</SearchDialogHeader>
				<SearchDialogList items={query.data !== "empty" ? query.data : null} />
				<SearchDialogFooter>
					<TagsList tag={tag} onTagChange={setTag}>
						<TagsListItem value="all">All</TagsListItem>
						<TagsListItem value="core">Core</TagsListItem>
						<TagsListItem value="cli">CLI</TagsListItem>
						<TagsListItem value="api">API</TagsListItem>
						<TagsListItem value="templates">Templates</TagsListItem>
					</TagsList>
				</SearchDialogFooter>
			</SearchDialogContent>
		</SearchDialog>
	);
}

import { getLLMText, source } from "@/lib/source";

export const revalidate = false;

const baseUrl = "https://docs.dokploy.com";

export async function GET() {
	const pages = source
		.getPages()
		.filter((page) => !page.url.startsWith("/docs/api/"));

	const scan = pages.map(getLLMText);
	const scanned = await Promise.all(scan);

	const content = [
		...scanned,
		"# API Reference",
		"",
		`For the complete API reference, see the OpenAPI specification: ${baseUrl}/openapi.json`,
	];

	return new Response(content.join("\n\n"));
}

import { source } from "@/lib/source";

export const revalidate = false;

const baseUrl = "https://docs.dokploy.com";

export function GET() {
	const pages = source.getPages();
	const docsPages = pages.filter(
		(page) => !page.url.startsWith("/docs/api/"),
	);

	const lines = [
		"# Dokploy Documentation",
		"",
		"> Dokploy is an open-source, self-hostable Platform as a Service (PaaS) that simplifies the deployment and management of applications, databases, and services.",
		"",
		"## Docs",
		"",
		...docsPages.map(
			(page) =>
				`- [${page.data.title}](${baseUrl}${page.url})${page.data.description ? `: ${page.data.description}` : ""}`,
		),
		"",
		"## API Reference",
		"",
		`- [OpenAPI Specification](${baseUrl}/openapi.json): Complete API reference in OpenAPI format`,
		"",
		"## Full Documentation",
		"",
		`- [llms-full.txt](${baseUrl}/llms-full.txt): All documentation pages as plain text`,
	];

	return new Response(lines.join("\n"));
}

import { source } from "@/lib/source";
import { createFromSource } from "fumadocs-core/search/server";
import type { InferPageType } from "fumadocs-core/source";

export const { GET } = createFromSource(source, {
	// https://docs.orama.com/docs/orama-js/supported-languages
	language: "english",
	// Configure tag filter based on the first slug (core, cli, api)
	buildIndex(page: InferPageType<typeof source>) {
		const tag = page.slugs[0] || "all";
		return {
			title: page.data.title,
			description: page.data.description,
			url: page.url,
			id: page.url,
			structuredData: page.data.structuredData,
			// Assign tag based on the first slug (core, cli, api)
			tag,
		} as any;
	},
});
